class Solution:
    def isCompletePrime(self, num: int) -> bool:
        def prime(x):
            if x < 2: return False
            d = 2
            while d * d <= x:
                if x % d == 0: return False
                d += 1
            return True
        p = num
        while p > 0:
            if not prime(p): return False
            p //= 10
        m = 10
        while m // 10 <= num:
            if not prime(num % m): return False
            m *= 10
        return True

