class Solution {
    private static final int[] PRIMES = build();
    private static int[] build() {
        int N = 31650;
        boolean[] sv = new boolean[N];
        java.util.Arrays.fill(sv, true);
        for (int i = 2; i * i < N; i++)
            if (sv[i]) for (int j = i*i; j < N; j += i) sv[j] = false;
        int cnt = 0;
        for (int i = 2; i < N; i++) if (sv[i]) cnt++;
        int[] ps = new int[cnt]; int k = 0;
        for (int i = 2; i < N; i++) if (sv[i]) ps[k++] = i;
        return ps;
    }
    private boolean isPrime(long x) {
        if (x < 2) return false;
        for (int p : PRIMES) {
            if ((long)p * p > x) break;
            if (x % p == 0) return false;
        }
        return true;
    }
    public boolean isCompletePrime(int num) {
        long p = num;
        while (p > 0) { if (!isPrime(p)) return false; p /= 10; }
        for (long m = 10; m / 10 <= num; m *= 10)
            if (!isPrime(num % m)) return false;
        return true;
    }
}

