        if (sv[i]) for (let j = i*i; j < N; j += i) sv[j] = false;
    for (let i = 2; i < N; i++) if (sv[i]) primes.push(i);
    const isPrime = x => {
        if (x < 2) return false;
        for (const p of primes) {
            if (p * p > x) break;
            if (x % p === 0) return false;
        }
        return true;
    };
    let p = num;
    while (p > 0) { if (!isPrime(p)) return false; p = Math.floor(p / 10); }
    for (let m = 10; m / 10 <= num; m *= 10)
        if (!isPrime(num % m)) return false;
    return true;
};
